<script setup lang="ts">
/**
 * AppPreloader — Cinematic Logo Reveal
 * Phase 1: SVG BM monogram stroke-draw (2s)
 * Phase 2: Blue glow pulse (0.8s)
 * Phase 3: Logo shrinks + fades, counter blur-to-sharp (1.8s)
 * Phase 4: Counter out (0.4s)
 * Phase 5: Curtain wipe up → reveals hero (0.8s)
 * Total: ~6s cinematic sequence
 */

const emit = defineEmits<{
  complete: []
  done: []
}>()

const logoRef = ref<SVGSVGElement>()
const counterRef = ref<HTMLElement>()
const curtainRef = ref<HTMLElement>()
const progress = ref(0)

const formattedCounter = computed(() =>
  String(Math.round(progress.value)).padStart(3, '0'),
)

onMounted(async () => {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    emit('complete')
    await nextTick()
    emit('done')
    return
  }

  // Quick reveal on revisit
  const hasVisited = sessionStorage.getItem('bm-visited')
  if (hasVisited) {
    runQuickReveal()
    return
  }

  sessionStorage.setItem('bm-visited', '1')
  runCinematic()
})

async function runQuickReveal() {
  progress.value = 100

  await new Promise(r => setTimeout(r, 100))
  emit('complete')

  if (curtainRef.value) {
    curtainRef.value.style.transition = 'transform 0.5s cubic-bezier(0.77, 0, 0.175, 1)'
    curtainRef.value.style.transform = 'translateY(-100%)'
  }

  await new Promise(r => setTimeout(r, 500))
  emit('done')
}

async function runCinematic() {
  const gsap = (await import('gsap')).default

  const tl = gsap.timeline({
    onComplete: () => {
      emit('done')
    },
  })

  const logoPaths = logoRef.value?.querySelectorAll('path')
  if (!logoPaths?.length)
    return

  // Measure path lengths and set initial stroke-dash state
  logoPaths.forEach((path) => {
    const len = path.getTotalLength()
    gsap.set(path, {
      strokeDasharray: len,
      strokeDashoffset: len,
      fill: 'transparent',
      stroke: '#ffffff',
      strokeWidth: 2,
    })
  })

  if (counterRef.value)
    gsap.set(counterRef.value, { opacity: 0, filter: 'blur(12px)' })
  if (curtainRef.value)
    gsap.set(curtainRef.value, { yPercent: 0 })

  // Phase 1: Draw SVG strokes (0s → 2s)
  tl.to(logoPaths, {
    strokeDashoffset: 0,
    duration: 2,
    ease: 'power3.inOut',
    stagger: 0.15,
  })

  // Phase 2: Electric blue glow pulse (2s → 2.8s)
  tl.to(logoPaths, {
    filter: 'drop-shadow(0 0 40px rgba(0, 71, 255, 0.9))',
    duration: 0.4,
    ease: 'power2.in',
  })
  tl.to(logoPaths, {
    filter: 'drop-shadow(0 0 8px rgba(0, 71, 255, 0.2))',
    duration: 0.4,
    ease: 'power2.out',
  })

  // Phase 3: Fill paths + shrink logo + counter appears (2.8s → 4.6s)
  tl.to(logoPaths, {
    fill: '#ffffff',
    stroke: 'transparent',
    duration: 0.5,
    ease: 'power2.inOut',
  }, '-=0.2')

  if (logoRef.value) {
    tl.to(logoRef.value, {
      scale: 0.5,
      opacity: 0.2,
      filter: 'blur(10px)',
      duration: 0.8,
      ease: 'expo.inOut',
    }, '-=0.3')
  }

  // Counter blur-to-sharp entrance
  if (counterRef.value) {
    tl.to(counterRef.value, {
      opacity: 1,
      filter: 'blur(0px)',
      duration: 0.5,
      ease: 'power3.out',
    }, '-=0.6')
  }

  // Counter 0 → 100
  tl.to(progress, {
    value: 100,
    duration: 1.8,
    ease: 'power2.inOut',
  }, '-=0.3')

  // Phase 4: Counter out (4.6s → 5.0s)
  if (counterRef.value) {
    tl.to(counterRef.value, {
      opacity: 0,
      scale: 1.3,
      filter: 'blur(12px)',
      duration: 0.4,
      ease: 'power3.in',
    })
  }

  // Emit complete → hero can start preparing
  tl.add(() => {
    emit('complete')
  })

  // Phase 5: Curtain wipe up (5.0s → 5.8s)
  if (curtainRef.value) {
    tl.to(curtainRef.value, {
      yPercent: -100,
      duration: 0.8,
      ease: 'expo.inOut',
    }, '+=0.1')
  }
}
</script>

